<template>
  <div v-if="state" class="app-shell">
    <header class="topbar">
      <div class="brand"><span class="day-mark">14</span><div><b>AI Challenge</b><small>Deterministic Invariants</small></div></div>
      <div class="topbar-title"><span class="eyebrow">ТЕМА УРОКА</span><h1>Инварианты агента</h1></div>
      <div class="header-actions"><span class="profile-badge"><i>{{ state.active_profile.name.slice(0,1) }}</i>{{ state.active_profile.name }}</span><button class="ghost settings-button" @click="showSettings=true">⚙ <span>Память и профиль</span></button></div>
    </header>
    <section class="workspace">
      <aside class="lesson-panel">
        <div><span class="eyebrow">ДЕМО-СЦЕНАРИЙ</span><h2>{{ selectedDemo.title }}</h2><p>{{ selectedDemo.description }} Детерминированный preflight выполняется до обращения к модели.</p></div>
        <div class="stack-form"><label>Сценарий<select v-model="selectedDemoKey"><option v-for="(scenario,key) in demoScenarios" :key="key" :value="key">{{ scenario.label }}</option></select></label></div>
        <button class="primary full demo-fill" :disabled="busy" @click="fillDemoTask">✦ Заполнить рабочую задачу</button>
        <button class="secondary full demo-action" :disabled="busy" @click="fillInvariantDemo">✦ Заполнить инвариант</button>
        <button class="secondary full demo-action" :disabled="busy" @click="fillCandidateDemo('conflict')">{{ selectedDemo.candidates.conflict.button }}</button>
        <button class="secondary full demo-action" :disabled="busy" @click="fillCandidateDemo('compatible')">{{ selectedDemo.candidates.compatible.button }}</button>
        <p class="action-note">Все четыре кнопки только заполняют черновики. Задачу, правило и запросы нужно сохранить или отправить отдельно.</p>
        <ol class="lesson-steps"><li v-for="(step,index) in selectedDemo.steps" :key="`${selectedDemoKey}-${index}`"><span>{{ index+1 }}</span><div><b>{{ step[0] }}</b><small>{{ step[1] }}</small></div></li></ol>
      </aside>

      <main class="chat-panel">
        <header class="chat-header"><div><span class="eyebrow">ДИАЛОГ С АГЕНТОМ</span><h2>{{ state.active_session.label }}</h2></div><span class="session-count">{{ state.active_session.messages.length }} сообщений</span></header>
        <div ref="messagesEl" class="messages">
          <div v-if="!state.active_session.messages.length" class="empty-state"><span class="empty-icon">◇</span><h2>Проверьте предложение</h2><p>Сначала сохраните инвариант справа, затем подставьте конфликтный или совместимый candidate слева.</p></div>
          <article v-for="message in state.active_session.messages" :key="message.id" class="message" :class="message.role"><div class="message-label">{{ message.role==='user' ? 'Вы' : state.active_profile.name }}</div><div v-if="message.role==='assistant'" class="bubble assistant-content" v-html="message.answer_html"></div><div v-else class="bubble">{{ message.content }}</div><button v-if="message.preview" class="preview-link" @click="preview=message.preview">Контекст ответа ↗</button></article>
          <article v-if="busy" class="message assistant"><div class="message-label">{{ state.active_profile.name }}</div><div class="bubble typing"><i></i><i></i><i></i></div></article>
        </div>
        <div class="composer-wrap">
          <div v-if="error" class="error-banner">{{ error }}</div><div v-if="lastCheck" class="check-banner" :class="lastCheck.allowed ? 'allowed' : 'rejected'"><b>{{ lastCheck.allowed ? '✓ Preflight: разрешено' : '× Preflight: отклонено' }}</b><span v-if="lastCheck.violations?.length">{{ lastCheck.violations.map(item=>`#${item.invariant_id}: ${item.reason}`).join(' · ') }}</span><span v-else>Активные правила не нарушены.</span></div>
          <div class="candidate-editor"><label>Проверяемое поле (ключ правила)<input v-model="candidateForm.field" maxlength="80" placeholder="backend_framework"></label><label>Предлагаемое значение<input v-model="candidateForm.value" maxlength="200" placeholder="fastapi"></label><label>Описание предлагаемого решения<textarea v-model="candidateForm.proposal" rows="2" maxlength="1000" placeholder="Что именно предлагается"></textarea><small>Preflight сравнивает ключ и значение. Описание и вопрос попадут к модели только после разрешения.</small></label></div><form class="composer" @submit.prevent="send"><textarea ref="composerEl" v-model="prompt" rows="2" maxlength="4000" placeholder="Что попросить агента объяснить…" @keydown.enter.exact.prevent="send"></textarea><button class="send" :disabled="busy || !canSend" aria-label="Проверить и отправить">↑</button></form><small>Отправка сначала запускает deterministic preflight; конфликт до модели не дойдёт.</small>
        </div>
      </main>

      <aside class="state-panel">
        <section class="editor-card invariant-card"><div class="panel-heading"><div><span class="eyebrow">INVARIANT STORE</span><h2>Новое правило</h2></div><span class="machine-status">{{ state.metrics.active_invariants }} активно</span></div><form class="stack-form" @submit.prevent="saveInvariant"><div class="double"><label>Категория<select v-model="invariantForm.category"><option value="architecture">Архитектура</option><option value="stack">Стек</option><option value="technical_decision">Техническое решение</option><option value="business_rule">Бизнес-правило</option></select></label><label>Оператор<select v-model="invariantForm.operator"><option value="equals">равно</option><option value="not_equals">не равно</option><option value="one_of">одно из</option><option value="not_one_of">не одно из</option></select></label></div><label>Поле<input v-model="invariantForm.field" maxlength="80" placeholder="backend_framework"></label><label>Ожидаемое значение<input v-model="invariantForm.expected_value" maxlength="200" placeholder="fastapi"></label><label>Описание<textarea v-model="invariantForm.description" maxlength="500" rows="2"></textarea></label><label>Причина<textarea v-model="invariantForm.reason" maxlength="500" rows="2"></textarea></label><label>Совместимая альтернатива<input v-model="invariantForm.compatible_alternative" maxlength="200"></label><button class="primary full" :disabled="busy || !canSaveInvariant">Сохранить инвариант</button></form></section>
        <section class="editor-card invariant-list-card"><span class="eyebrow">АКТИВНЫЕ И ОТКЛЮЧЁННЫЕ</span><h2>Инварианты</h2><div class="invariant-list"><div v-for="item in state.invariants" :key="item.id" :class="{inactive:!item.active}"><div><b>#{{ item.id }} · {{ item.description }}</b><small>{{ item.field }} {{ operatorLabel(item.operator) }} {{ item.expected_value }}</small></div><button class="chip" :disabled="busy" @click="toggleInvariant(item)">{{ item.active ? 'Отключить' : 'Включить' }}</button><button class="session-delete" :disabled="busy" @click="deleteInvariant(item.id)">×</button></div><p v-if="!state.invariants.length" class="hint">Сначала заполните и явно сохраните демо-инвариант.</p></div></section>
        <section class="editor-card task-card"><div class="panel-heading"><div><span class="eyebrow">РАБОЧИЙ КОНТЕКСТ</span><h2>Контекст задачи</h2></div><span class="unsaved-note">явное сохранение</span></div><form class="stack-form" @submit.prevent="saveTask"><label>Цель<input v-model="taskForm.goal" maxlength="500" placeholder="Что нужно получить"></label><label>Жёсткие ограничения<textarea v-model="taskForm.hard_constraints" maxlength="500" rows="2"></textarea></label><label>Данные<textarea v-model="taskForm.task_data" maxlength="500" rows="2"></textarea></label><label>Открытые вопросы<textarea v-model="taskForm.open_questions" maxlength="500" rows="2"></textarea></label><button class="secondary full" :disabled="busy || !taskForm.goal.trim()">Сохранить контекст</button></form></section>
      </aside>
    </section>

    <div v-if="showCreate" class="modal-backdrop" @click.self="showCreate=false"><section class="modal"><button class="modal-close" @click="showCreate=false">×</button><span class="eyebrow">НОВЫЙ ПРОФИЛЬ</span><h2>Создать профиль ответа</h2><form class="stack-form" @submit.prevent="createProfile"><label>Название<input v-model="createForm.name" maxlength="80" required></label><label>Роль и контекст<textarea v-model="createForm.role_context" maxlength="500" rows="2"></textarea></label><div class="triple"><label>Тон<select v-model="createForm.tone"><option value="friendly">Дружелюбный</option><option value="neutral">Нейтральный</option><option value="business">Деловой</option></select></label><label>Глубина<select v-model="createForm.detail_level"><option value="brief">Кратко</option><option value="balanced">Баланс</option><option value="deep">Глубоко</option></select></label><label>Формат<select v-model="createForm.response_format"><option value="paragraphs">Абзацы</option><option value="bullets">Список</option><option value="steps">Шаги</option><option value="table">Таблица</option></select></label></div><label>Язык<input v-model="createForm.language" maxlength="500"></label><label>Ограничения<textarea v-model="createForm.constraints" maxlength="500" rows="2"></textarea></label><button class="primary full">Создать и активировать</button></form></section></div>

    <div v-if="showSettings" class="modal-backdrop" @click.self="showSettings=false"><section class="modal settings-modal"><button class="modal-close" @click="showSettings=false">×</button><span class="eyebrow">СКРЫТО ОТ ГЛАВНОГО УРОКА</span><h2>Память и профиль</h2><div class="settings-tabs"><button v-for="tab in settingsTabs" :key="tab.id" :class="{active:settingsTab===tab.id}" @click="settingsTab=tab.id">{{ tab.label }}</button></div>
      <div v-if="settingsTab==='profiles'" class="settings-content"><div class="settings-heading"><div><h3>Профили ответа</h3><p>Выберите режим ответа или настройте активный профиль.</p></div><button class="secondary" @click="openCreateProfile">＋ Новый</button></div><div class="profile-list light"><button v-for="profile in state.profiles" :key="profile.id" class="profile-item" :class="{active:profile.id===state.active_profile.id}" :disabled="busy" @click="activateProfile(profile.id)"><span class="avatar">{{ profile.name.slice(0,1) }}</span><span><b>{{ profile.name }}</b><small>{{ toneLabel(profile.tone) }} · {{ detailLabel(profile.detail_level) }}</small></span><i v-if="profile.is_active">●</i></button></div><form class="stack-form settings-form" @submit.prevent="saveProfile"><label>Название<input v-model="profileForm.name" maxlength="80"></label><label>Роль и контекст<textarea v-model="profileForm.role_context" maxlength="500" rows="2"></textarea></label><div class="triple"><label>Тон<select v-model="profileForm.tone"><option value="friendly">Дружелюбный</option><option value="neutral">Нейтральный</option><option value="business">Деловой</option></select></label><label>Глубина<select v-model="profileForm.detail_level"><option value="brief">Кратко</option><option value="balanced">Баланс</option><option value="deep">Глубоко</option></select></label><label>Формат<select v-model="profileForm.response_format"><option value="paragraphs">Абзацы</option><option value="bullets">Список</option><option value="steps">Шаги</option><option value="table">Таблица</option></select></label></div><label>Язык<input v-model="profileForm.language" maxlength="500"></label><label>Ограничения<textarea v-model="profileForm.constraints" maxlength="500" rows="2"></textarea></label><button class="primary">Сохранить профиль</button></form></div>
      <div v-if="settingsTab==='sessions'" class="settings-content"><div class="settings-heading"><div><h3>Диалоги</h3><p>Диалоги принадлежат активному профилю.</p></div><button class="primary" :disabled="busy" @click="createSession">＋ Новый</button></div><div class="session-list light"><div v-for="session in state.sessions" :key="session.id" class="session-row" :class="{active:session.is_active}"><button class="session-activate" :disabled="busy" @click="activateSession(session.id)"><span>{{ session.branched_from_id ? '⑂' : '◌' }}</span><span><b>{{ session.label }}</b><small>{{ session.message_count }} сообщений</small></span></button><button class="session-delete" :disabled="busy" @click.stop="deleteSession(session)">×</button></div></div><div class="dialog-actions"><button class="secondary" :disabled="busy" @click="branchSession">⑂ Создать ветку</button><button class="danger-button" :disabled="busy" @click="resetSession">Очистить чат</button></div></div>
      <div v-if="settingsTab==='memory'" class="settings-content"><h3>Долговременная память</h3><p>Явные решения и знания доступны всем профилям.</p><div class="memory-items"><div v-for="item in state.long_term" :key="item.id" class="memory-item"><span>{{ item.entry_type==='decision' ? 'Решение' : 'Знание' }}</span><p>{{ item.content }}</p><button :disabled="busy" @click="deleteLongTerm(item.id)">×</button></div><p v-if="!state.long_term.length" class="hint">Записей пока нет.</p></div><form class="inline-add" @submit.prevent="addLongTerm"><select v-model="memoryType"><option value="knowledge">Знание</option><option value="decision">Решение</option></select><input v-model="memoryText" maxlength="500" placeholder="Добавить явную запись"><button :disabled="busy || !memoryText.trim()">＋</button></form></div>
      <div v-if="settingsTab==='model'" class="settings-content"><h3>Модель и контекст</h3><form class="stack-form" @submit.prevent="showSettings=false"><div class="double"><label>Провайдер<select v-model="controls.provider"><option value="deepseek">DeepSeek</option><option value="openrouter">OpenRouter</option></select></label><label>Модель<select v-model="controls.model"><template v-if="controls.provider==='deepseek'"><option value="deepseek-flash">DeepSeek Flash</option><option value="deepseek-v4-pro">DeepSeek V4 Pro</option></template><option v-else value="openrouter/free">OpenRouter Free</option></select></label></div><label>Режим памяти<select v-model="controls.compression_mode"><option value="full_session">Полная сессия</option><option value="sliding_window">Sliding Window</option><option value="sticky_facts">Sticky Facts</option><option value="rolling_summary">Rolling summary</option><option value="explicit_only">Только явная память</option></select></label><label v-if="['sliding_window','sticky_facts'].includes(controls.compression_mode)">Размер окна<input v-model.number="controls.window_size" type="number" min="2" max="20" step="2"></label><div v-if="controls.compression_mode==='rolling_summary'" class="double"><label>Batch<input v-model.number="controls.batch_size" type="number" min="2" max="20" step="2"></label><label>Оставить<input v-model.number="controls.keep_recent" type="number" min="2" max="20" step="2"></label></div><div class="double"><label>Temperature<input v-model.number="controls.temperature" type="number" min="0" max="2" step="0.1"></label><label>Max tokens<input v-model="controls.max_tokens" type="number" min="1" max="4096" placeholder="По умолчанию"></label></div><button class="primary">Готово</button></form><section class="danger-zone"><span class="eyebrow">ОПАСНАЯ ЗОНА</span><h3>Удалить все данные</h3><p>Будут удалены профили, диалоги, память, задача, инварианты и журнал проверок.</p><button class="danger-button full" :disabled="busy" @click="clearAll">Удалить всё и начать заново</button></section></div>
    </section></div>
    <div v-if="preview" class="modal-backdrop" @click.self="preview=null"><section class="modal preview-modal"><button class="modal-close" @click="preview=null">×</button><span class="eyebrow">ТОЧНЫЙ SNAPSHOT</span><h2>Контекст ответа</h2><div class="snapshot"><b>{{ preview.profile_snapshot?.name }}</b><span>{{ preview.profile_snapshot?.tone }} · {{ preview.profile_snapshot?.detail_level }} · {{ preview.profile_snapshot?.response_format }}</span></div><pre>{{ JSON.stringify(preview, null, 2) }}</pre></section></div>
  </div>
  <div v-else class="loading">Загружаем агент с инвариантами…</div>
</template>

<script setup>
import { computed, nextTick, onMounted, reactive, ref, watch } from 'vue'
import { backendDemoTask, demoScenarios } from './demo-presets'
const state=ref(null),prompt=ref(''),busy=ref(false),error=ref(''),lastCheck=ref(null),messagesEl=ref(null),composerEl=ref(null)
const showCreate=ref(false),showSettings=ref(false),preview=ref(null),settingsTab=ref('profiles')
const memoryType=ref('knowledge'),memoryText=ref(''),selectedDemoKey=ref('stack')
const settingsTabs=[{id:'profiles',label:'Профили'},{id:'sessions',label:'Диалоги'},{id:'memory',label:'Память'},{id:'model',label:'Модель'}]
const blankProfile={name:'',role_context:'',language:'Русский',tone:'neutral',detail_level:'balanced',response_format:'paragraphs',constraints:''}
const createForm=reactive({...blankProfile}),profileForm=reactive({...blankProfile})
const taskForm=reactive({goal:'',hard_constraints:'',task_data:'',open_questions:''})
const invariantForm=reactive({category:'stack',field:'',operator:'equals',expected_value:'',description:'',reason:'',compatible_alternative:'',active:true})
const candidateForm=reactive({field:'',value:'',proposal:''})
const controls=reactive({provider:'deepseek',model:'deepseek-flash',temperature:0,max_tokens:'',compression_mode:'full_session',window_size:6,batch_size:10,keep_recent:6})
const selectedDemo=computed(()=>demoScenarios[selectedDemoKey.value])
const canSend=computed(()=>prompt.value.trim()&&candidateForm.field.trim()&&candidateForm.value.trim()&&candidateForm.proposal.trim())
const canSaveInvariant=computed(()=>['field','expected_value','description','reason','compatible_alternative'].every(key=>invariantForm[key].trim()))
async function api(path,options={}){error.value='';const response=await fetch(path,{headers:{'Content-Type':'application/json'},...options});const data=await response.json().catch(()=>({}));if(!response.ok){const issue=new Error(data.detail?.message||data.detail||'Не удалось выполнить запрос');issue.detail=data.detail;throw issue}return data}
function sync(next){state.value=next;Object.assign(profileForm,Object.fromEntries(Object.keys(blankProfile).map(key=>[key,next.active_profile[key]??''])));Object.assign(taskForm,Object.fromEntries(Object.keys(taskForm).map(key=>[key,next.task?.[key]??''])));nextTick(scrollBottom)}
function scrollBottom(){if(messagesEl.value)messagesEl.value.scrollTop=messagesEl.value.scrollHeight}
async function mutate(path,method='POST',body){busy.value=true;try{sync(await api(path,{method,body:body===undefined?undefined:JSON.stringify(body)}))}catch(e){error.value=e.message}finally{busy.value=false}}
const activateProfile=id=>mutate(`/api/profiles/${id}/activate`),createSession=()=>mutate('/api/sessions'),activateSession=id=>mutate(`/api/sessions/${id}/activate`),branchSession=()=>mutate(`/api/sessions/${state.value.active_session.id}/branch`)
async function resetSession(){if(confirm('Удалить историю этого диалога?'))await mutate(`/api/sessions/${state.value.active_session.id}/reset`)}
async function deleteSession(session){if(confirm(`Удалить диалог «${session.label}» вместе с его сообщениями?`))await mutate(`/api/sessions/${session.id}`,'DELETE')}
async function clearAll(){if(!confirm('Удалить все профили, диалоги, рабочую и долговременную память? Это действие нельзя отменить.'))return;await mutate('/api/memory/clear');if(!error.value)showSettings.value=false}
async function saveProfile(){await mutate(`/api/profiles/${state.value.active_profile.id}`,'PUT',profileForm)}
async function createProfile(){await mutate('/api/profiles','POST',createForm);if(!error.value){showCreate.value=false;Object.assign(createForm,blankProfile)}}
function openCreateProfile(){showSettings.value=false;showCreate.value=true}
function fillInvariantDemo(){Object.assign(invariantForm,selectedDemo.value.invariant)}
function fillCandidateDemo(kind){const draft=selectedDemo.value.candidates[kind];Object.assign(candidateForm,{field:draft.field,value:draft.value,proposal:draft.proposal});prompt.value=draft.prompt;lastCheck.value=null;nextTick(()=>composerEl.value?.focus())}
async function saveInvariant(){await mutate('/api/invariants','POST',invariantForm)}
async function toggleInvariant(item){await mutate(`/api/invariants/${item.id}/active`,'PATCH',{active:!item.active})}
async function deleteInvariant(id){await mutate(`/api/invariants/${id}`,'DELETE')}
function fillDemoTask(){Object.assign(taskForm,backendDemoTask);nextTick(()=>document.querySelector('.task-card input')?.focus())}
async function saveTask(){await mutate('/api/task','PUT',taskForm)}
async function addLongTerm(){await mutate('/api/long-term','POST',{entry_type:memoryType.value,content:memoryText.value});if(!error.value)memoryText.value=''}
const deleteLongTerm=id=>mutate(`/api/long-term/${id}`,'DELETE')
function insertPrompt(text){prompt.value=text;nextTick(()=>composerEl.value?.focus())}
async function send(){if(busy.value||!canSend.value)return;const question=prompt.value;prompt.value='';busy.value=true;lastCheck.value=null;await nextTick();scrollBottom();try{const result=await api('/api/ask',{method:'POST',body:JSON.stringify({prompt:question,candidate:{...candidateForm},controls}),headers:{'Content-Type':'application/json'}});lastCheck.value=result.preview.invariant_check;sync(result.state)}catch(e){prompt.value=question;error.value=e.message;lastCheck.value=e.detail?.invariant_check||null}finally{busy.value=false;await nextTick();scrollBottom()}}
const toneLabel=value=>({friendly:'дружелюбно',neutral:'нейтрально',business:'по-деловому'}[value]||value),detailLabel=value=>({brief:'кратко',balanced:'баланс',deep:'глубоко'}[value]||value)
const operatorLabel=value=>({equals:'=',not_equals:'≠',one_of:'∈',not_one_of:'∉'}[value]||value)
watch(()=>state.value?.active_session?.messages?.length,()=>nextTick(scrollBottom));watch(()=>controls.provider,provider=>{if(provider==='openrouter')controls.model='openrouter/free';else if(!['deepseek-flash','deepseek-v4-pro'].includes(controls.model))controls.model='deepseek-flash'});onMounted(async()=>{try{sync(await api('/api/state'))}catch(e){error.value=e.message}})
</script>
